wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1641834752270092)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Procesar turno con PKG_TURNOS'
,p_static_id=>'process-form-turno'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_fecha  DATE := TO_DATE(:P3_FECHA_HORA);',
'    v_prof   turno.id_profesional%TYPE;',
'    v_serv   turno.id_servicio%TYPE;',
'    v_dia    turno.fecha_hora%TYPE;',
'    v_hora   turno.hora_inicio%TYPE;',
'    v_estado turno.estado%TYPE;',
'    v_obs    turno.observaciones%TYPE;',
'BEGIN',
'    IF :REQUEST = ''CREATE'' THEN',
'        -- Alta: valida horario, disponibilidad y solapamiento',
'        PKG_TURNOS.RESERVAR_TURNO(',
'            p_id_cliente     => :P3_ID_CLIENTE,',
'            p_id_profesional => :P3_ID_PROFESIONAL,',
'            p_id_servicio    => :P3_ID_SERVICIO,',
'            p_fecha_hora     => v_fecha,',
'            p_hora_inicio    => :P3_HORA_INICIO,',
'            p_observaciones  => :P3_OBSERVACIONES);',
'',
'    ELSIF :REQUEST = ''SAVE'' THEN',
'        SELECT id_profesional, id_servicio, fecha_hora, hora_inicio, estado, observaciones',
'          INTO v_prof, v_serv, v_dia, v_hora, v_estado, v_obs',
'          FROM turno',
'         WHERE id_turno = :P3_ID_TURNO;',
'',
unistr('        -- Reprogramaci\00F3n: solo si cambi\00F3 profesional, servicio, d\00EDa u hora'),
'        IF v_prof <> :P3_ID_PROFESIONAL',
'        OR v_serv <> :P3_ID_SERVICIO',
'        OR TRUNC(v_dia) <> TRUNC(v_fecha)',
'        OR v_hora <> :P3_HORA_INICIO THEN',
'            PKG_TURNOS.MODIFICAR_TURNO(:P3_ID_TURNO, :P3_ID_PROFESIONAL, :P3_ID_SERVICIO,',
'                                       v_fecha, :P3_HORA_INICIO, :P3_OBSERVACIONES);',
'        ELSIF NVL(v_obs, ''#'') <> NVL(:P3_OBSERVACIONES, ''#'') THEN',
'            UPDATE turno SET observaciones = :P3_OBSERVACIONES',
'             WHERE id_turno = :P3_ID_TURNO;',
'        END IF;',
'',
'        -- Cambio de estado: pasa por las reglas del paquete',
'        IF :P3_ESTADO <> v_estado THEN',
'            SP_CAMBIAR_ESTADO_TURNO(:P3_ID_TURNO, :P3_ESTADO);',
'        END IF;',
'',
'    ELSIF :REQUEST = ''DELETE'' THEN',
'        RAISE_APPLICATION_ERROR(-20012,',
unistr('            ''Los turnos no se eliminan. Para anularlo, cambi\00E1 su estado a CANCELADO.'');'),
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>1641834752270092
,p_created_on=>wwv_flow_imp.dz('20260624154757Z')
,p_updated_on=>wwv_flow_imp.dz('20261009091904Z')
,p_created_by=>'ADMIN'
,p_updated_by=>'ADMIN'
);
end;
